/// One merged `AppButton` look (base, state, size): colours are role keys, sizes pt/dp.
nonisolated public struct ButtonAppearance: Sendable, Equatable {
  public let backgroundColor: AppColorRole?
  public let textColor: AppColorRole
  public let borderColor: AppColorRole?
  public let spinnerColor: AppColorRole?
  public let overlayColor: AppColorRole?
  public let borderWidth: Double?
  public let typography: AppTextStyle
  public let rounded: Double
  public let height: Double
  public let paddingTop: Double
  public let paddingEnd: Double
  public let paddingBottom: Double
  public let paddingStart: Double
  public let iconSize: AppIconSize
  public let iconGap: Double
  public let focusRing: FocusRingTokens?
}

/// An allowed `AppButton` combination and its merged look.
nonisolated public struct ButtonLook: Sendable, Equatable {
  public let variant: ButtonVariant
  public let size: ButtonSize
  public let state: ButtonState
  public let appearance: ButtonAppearance
}

