  public static let light: ButtonSpec = Light.spec
  public static let dark: ButtonSpec = Dark.spec
  public static let brand: ButtonSpec = Brand.spec
  public static let hcLight: ButtonSpec = HcLight.spec
  public static let hcDark: ButtonSpec = HcDark.spec

  /// The merged look of an allowed combination; none when the contract does not allow it.
  public func appearance(variant: ButtonVariant, size: ButtonSize, state: ButtonState) -> ButtonAppearance? {
    looks.first { $0.variant == variant && $0.size == size && $0.state == state }?.appearance
  }
}

/// One `AppButton` gallery cell and its test ID.
nonisolated public struct ButtonGalleryEntry: Sendable, Equatable {
  public let variant: ButtonVariant
  public let size: ButtonSize
  public let state: ButtonState
  public let testId: String
}

/// Variants of `AppChip` (chip.yaml, board C03), each with its contract id.
nonisolated public enum ChipVariant: String, CaseIterable, Sendable {
  case weather
  case context
  case conditionSunny = "condition-sunny"
  case conditionRain = "condition-rain"
  case conditionCold = "condition-cold"
  case conditionHot = "condition-hot"
  case conditionWindy = "condition-windy"
  case conditionSnow = "condition-snow"
  case conditionEvening = "condition-evening"
  case override
  case reason
  case choice
  case swatch
  case filter
  case filterMenu = "filter-menu"
  case groupSort = "group-sort"
  case neverSuggest = "never-suggest"
  case softDislike = "soft-dislike"
  case add
  case neverSuggestAdd = "never-suggest-add"

  /// The accessibility role of the variant.
  public var role: ChipRole {
    switch self {
    case .weather: .button
    case .context: .button
    case .conditionSunny: .button
    case .conditionRain: .button
    case .conditionCold: .button
    case .conditionHot: .button
    case .conditionWindy: .button
    case .conditionSnow: .button
    case .conditionEvening: .button
    case .override: .button
    case .reason: .disclosure
    case .choice: .selectable
    case .swatch: .selectable
    case .filter: .selectable
    case .filterMenu: .menu
    case .groupSort: .menu
    case .neverSuggest: .button
    case .softDislike: .button
    case .add: .button
    case .neverSuggestAdd: .button
    }
  }

  /// The parts the variant draws beside its label, in contract order.
  public var parts: [ChipPart] {
    switch self {
    case .weather: []
    case .context: []
    case .conditionSunny: []
    case .conditionRain: []
    case .conditionCold: []
    case .conditionHot: []
    case .conditionWindy: []
    case .conditionSnow: []
    case .conditionEvening: []
    case .override: [.detail]
    case .reason: []
    case .choice: []
    case .swatch: [.swatch]
    case .filter: [.detail]
    case .filterMenu: []
    case .groupSort: [.prefix]
    case .neverSuggest: []
    case .softDislike: []
    case .add: []
    case .neverSuggestAdd: []
    }
  }
}

/// Sizes of `AppChip` (chip.yaml, board C03), each with its contract id.
nonisolated public enum ChipSize: String, CaseIterable, Sendable {
  case compact
  case small
  case medium
  case large
}

/// States of `AppChip` (chip.yaml, board C03), each with its contract id.
nonisolated public enum ChipState: String, CaseIterable, Sendable {
  case enabled
  case pressed
  case focused
  case disabled
  case selected
  case selectedPressed = "selected-pressed"
  case selectedFocused = "selected-focused"
  case selectedDisabled = "selected-disabled"
  case expanded
  case expandedPressed = "expanded-pressed"
  case expandedFocused = "expanded-focused"
}

/// Accessibility roles of `AppChip` (chip.yaml, board C03), each with its contract id.
nonisolated public enum ChipRole: String, CaseIterable, Sendable {
  case button
  case selectable
  case disclosure
  case menu
}

/// Values of the `selection` prop of `AppChip` (chip.yaml, board C03).
nonisolated public enum ChipSelection: String, CaseIterable, Sendable {
  case multiple
  case single
}

/// Part kinds of `AppChip` (chip.yaml, board C03), each with its contract id.
nonisolated public enum ChipPartKind: String, CaseIterable, Sendable {
  case text
  case swatch
}

/// Part positions of `AppChip` (chip.yaml, board C03), each with its contract id.
nonisolated public enum ChipPartPosition: String, CaseIterable, Sendable {
  case beforeLabel = "before-label"
  case afterLabel = "after-label"
}

/// Parts of `AppChip` beside its label (chip.yaml `parts`), in contract order.
nonisolated public enum ChipPart: String, CaseIterable, Sendable {
  case prefix
  case swatch
  case detail

  /// What fills the part (contract `kind`).
  public var kind: ChipPartKind {
    switch self {
    case .prefix: .text
    case .swatch: .swatch
    case .detail: .text
    }
  }

  /// Where it sits (contract `position`).
  public var position: ChipPartPosition {
    switch self {
    case .prefix: .beforeLabel
    case .swatch: .beforeLabel
    case .detail: .afterLabel
    }
  }

  /// The string resource of the copy drawn before its text, in both apps (`separator`).
  public var separatorKey: String? {
    switch self {
    case .prefix: nil
    case .swatch: nil
    case .detail: "ds_chip_detail_separator"
    }
  }

  /// Its line opens with the variant's leading icon instead of the label's (`icon`).
  public var takesLeadingIcon: Bool {
    switch self {
    case .prefix: false
    case .swatch: false
    case .detail: false
    }
  }
}

/// Where an icon of `AppChip` comes from: a glyph of the icon set, or the caller's prop.
nonisolated public enum ChipIconSource: Sendable, Equatable {
  /// A glyph of the icon set (`AppIconName`).
  case glyph(name: AppIconName)

  /// The caller's icon prop.
  case prop
}

