  public static let light: ChipSpec = Light.spec
  public static let dark: ChipSpec = Dark.spec
  public static let brand: ChipSpec = Brand.spec
  public static let hcLight: ChipSpec = HcLight.spec
  public static let hcDark: ChipSpec = HcDark.spec

  /// The merged look of an allowed combination; none when the contract does not allow it.
  public func appearance(variant: ChipVariant, size: ChipSize, state: ChipState) -> ChipAppearance? {
    looks.first { $0.variant == variant && $0.size == size && $0.state == state }?.appearance
  }
}

/// One `AppChip` gallery cell and its test ID.
nonisolated public struct ChipGalleryEntry: Sendable, Equatable {
  public let variant: ChipVariant
  public let size: ChipSize
  public let state: ChipState
  public let testId: String
}

