}

/// Accessibility roles of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id.
nonisolated public enum ReasonRowRole: String, CaseIterable, Sendable {
  case region
}

/// Part kinds of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id.
nonisolated public enum ReasonRowPartKind: String, CaseIterable, Sendable {
  case text
}

/// Part positions of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id.
nonisolated public enum ReasonRowPartPosition: String, CaseIterable, Sendable {
  case line
}

/// Parts of `AppReasonRow` beside its label (reason-row.yaml `parts`), in contract order.
nonisolated public enum ReasonRowPart: String, CaseIterable, Sendable {
  case fact
  case freshness

  /// What fills the part (contract `kind`).
  public var kind: ReasonRowPartKind {
    switch self {
    case .fact: .text
    case .freshness: .text
    }
  }

  /// Where it sits (contract `position`).
  public var position: ReasonRowPartPosition {
    switch self {
    case .fact: .line
    case .freshness: .line
    }
  }

  /// The string resource of the copy drawn before its text, in both apps (`separator`).
  public var separatorKey: String? {
    switch self {
    case .fact: nil
    case .freshness: nil
    }
  }

  /// Its line opens with the variant's leading icon instead of the label's (`icon`).
  public var takesLeadingIcon: Bool {
    switch self {
    case .fact: true
    case .freshness: false
    }
  }
}

