  public static let light: TagSpec = Light.spec
  public static let dark: TagSpec = Dark.spec
  public static let brand: TagSpec = Brand.spec
  public static let hcLight: TagSpec = HcLight.spec
  public static let hcDark: TagSpec = HcDark.spec

  /// The merged look of an allowed combination; none when the contract does not allow it.
  public func appearance(variant: TagVariant, size: TagSize, state: TagState) -> TagAppearance? {
    looks.first { $0.variant == variant && $0.size == size && $0.state == state }?.appearance
  }
}

/// One `AppTag` gallery cell and its test ID.
nonisolated public struct TagGalleryEntry: Sendable, Equatable {
  public let variant: TagVariant
  public let size: TagSize
  public let state: TagState
  public let testId: String
}

/// The gallery sections of the components, in board order, each with its contract id.
nonisolated public enum GalleryComponent: String, CaseIterable, Sendable {
  case button
  case icon
  case badge
  case chip
  case reasonRow = "reason-row"
  case tag

  /// The section title: the board and the contract `gallery.title`.
  public var title: String {
    switch self {
    case .button: "C01 Buttons"
    case .icon: "C02 Icons"
    case .badge: "C03 Badges"
    case .chip: "C03 Chips"
    case .reasonRow: "C03 Reason row"
    case .tag: "C03 Tags"
    }
  }

  /// The kebab-case title: the section id is `ds-gallery-section-<slug>`.
  public var slug: String {
    switch self {
    case .button: "c01-buttons"
    case .icon: "c02-icons"
    case .badge: "c03-badges"
    case .chip: "c03-chips"
    case .reasonRow: "c03-reason-row"
    case .tag: "c03-tags"
    }
  }
}

